const resp = $input.item.json;
let content = null;
try { content = resp?.choices?.[0]?.message?.content; } catch(e) {}
if(!content) { try { content = resp?.candidates?.[0]?.content?.parts?.[0]?.text; } catch(e) {} }
if (!content) throw new Error('Sin respuesta: ' + JSON.stringify(resp || {}).slice(0, 500));

// Propagar campos del item anterior (OpenRouter HTTP pierde JSON previo)
let prevJson = {};
try {
  const buildItems = $('Build_Gemini_Payload').all();
  prevJson = buildItems[Math.min($itemIndex, buildItems.length-1)]?.json || {};
} catch(e) {}

// Eliminar payload pesado
delete prevJson.openrouter_payload;
delete prevJson.pdf_base64;

return { json: { ...prevJson, output: content }, binary: $input.item.binary };

// Restaurar binary para el adjunto del email de aviso leve
return [{
  json: $input.item.json,
  binary: $('Merge_PDFs_Centros').item.binary
}];

// Acuse de recibo al remitente — AGREGA todas las facturas archivadas del correo.
// Fuente fiable: Prep_DocuWare_Centros (lleva ...d completo + binary.pdf_final).
// NO depende del orden de salida de Google Sheets (append no garantiza alineación).
const archived = $('Prep_DocuWare_Centros').all();
const trigger  = $('Email Trigger (IMAP)1').first().json;
let _fromRaw = trigger.from?.value?.[0]?.address || trigger.from?.address || String(trigger.from || '');
const _emailMatch = String(_fromRaw).match(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/i);
const emailRemitente = (_emailMatch ? _emailMatch[0] : String(_fromRaw)).toLowerCase().trim();
const remitenteInterno = emailRemitente.endsWith('@aldahotels.com');
// Diagnóstico: guardamos el valor crudo del remitente tal cual llegó del
// trigger IMAP, para poder ver en el Excel exactamente qué formato tenía
// si el filtro de interno/externo alguna vez se comporta de forma inesperada.
const _fromDiagnostico = String(_fromRaw).slice(0, 150);
const now = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' });

const facturas = archived.map(x => x.json || {});

// ---- Adjuntar TODOS los PDF (uno por factura) ----
// Adjuntar el PDF SOLO si el binario es resoluble (tiene .id en modo 'separate'
// o .data en modo inline). Si no, el acuse se envía IGUAL sin adjunto: el email
// de confirmación es lo importante y el PDF ya está archivado en DocuWare.
// Un adjunto roto haría fallar el nodo SMTP y no llegaría ningún correo.
const outBinary = {};
const attachKeys = [];
archived.forEach((x, i) => {
  const pdf = x.binary?.pdf_final;
  const resoluble = pdf && (pdf.id || pdf.data);  // referencia externa o base64 real
  if(resoluble){
    const key = 'factura_' + i;
    const nombre = ((facturas[i].factura_numero || ('factura_' + (i+1))) + '').replace(/[^a-zA-Z0-9._-]/g, '_');
    outBinary[key] = { ...pdf, fileName: nombre + '.pdf', fileExtension: 'pdf', mimeType: 'application/pdf' };
    attachKeys.push(key);
  }
});

// ---- Estado de una factura ----
function estadoDe(d){
  const esGrave = d.tiene_error_grave;
  const esLeve  = !d.tiene_error_grave && d.tiene_error_leve;
  if(esGrave){
    let mensaje = (d.motivo_revision === 'factura_dirigida_a_sociedad')
      ? 'Dirigida a la sociedad <strong>' + (d.hotel_destino_factura || '') + '</strong> sin hotel específico. Requiere imputación manual en Odoo antes de archivar.'
      : 'Requiere revisión por parte de nuestro equipo antes de ser archivada.';
    return { estado:'Pendiente de revisión', emoji:'🔴', colorBg:'#FEE2E2', colorBorder:'#991B1B', mensaje };
  }
  if(esLeve){
    let mensaje;
    if(d.motivo_revision === 'factura_dirigida_a_sociedad'){
      mensaje = 'Dirigida a la sociedad <strong>' + (d.hotel_destino_factura || '') + '</strong> sin hotel concreto. Asignada provisionalmente a costes generales; impútala manualmente en Odoo.';
    } else if(d.motivo_revision === 'costes_generales_posible_hotel'){
      mensaje = 'Asignada a costes generales, pero hay una dirección que podría ser un hotel específico. Verifica la imputación.';
    } else {
      mensaje = 'Archivada en DocuWare con algunos avisos.';
    }
    return { estado:'Procesada con avisos', emoji:'🟡', colorBg:'#FEF3C7', colorBorder:'#D97706', mensaje };
  }
  return { estado:'Procesada correctamente', emoji:'✅', colorBg:'#D1FAE5', colorBorder:'#065F46', mensaje:'Recibida y archivada automáticamente en DocuWare.' };
}

const HEAD = `<div style="background:#1F2937;padding:16px 20px;border-radius:6px;margin-bottom:24px">
  <img src="https://www.aldahotels.es/img/logo-alda-white.png" alt="Alda Hotels" style="height:32px" onerror="this.style.display='none'">
  <span style="color:#fff;font-size:16px;font-weight:bold;margin-left:12px">Alda Hotels · Facturación</span>
</div>`;
const FOOT = `<p style="font-size:11px;color:#999;margin-top:24px;text-align:center">Este es un mensaje automático del sistema de facturación de Alda Hotels.<br>Por favor, no respondas a este correo.</p>`;
const fmtImporte = v => (v != null && v !== '') ? (v + ' €') : '—';

let html, acuse_subject;
const anyGrave = facturas.some(d => d.tiene_error_grave);
const anyLeve  = facturas.some(d => !d.tiene_error_grave && d.tiene_error_leve);

if(facturas.length <= 1){
  // ---------- CASO 1 FACTURA (formato detallado original) ----------
  const d = facturas[0] || {};
  const s = estadoDe(d);
  const erroresHtml = [
    ...((d.errores_graves)||[]).map(e => `<li style="color:#991B1B"><strong>Error:</strong> ${e}</li>`),
    ...((d.errores_leves)||[]).map(e => `<li style="color:#92400E"><strong>Aviso:</strong> ${e}</li>`)
  ].join('');
  html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;font-size:13px;color:#111;padding:24px;max-width:620px;margin:0 auto">
${HEAD}
<div style="background:${s.colorBg};border-left:4px solid ${s.colorBorder};padding:14px 18px;border-radius:4px;margin-bottom:20px">
  <strong>${s.emoji} ${s.estado}</strong>
</div>
<p>${s.mensaje}</p>
<table style="width:100%;border-collapse:collapse;font-size:12px;margin:16px 0">
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold;width:40%">Proveedor</td><td style="padding:7px 10px">${d.proveedor_nombre || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold;width:40%">Nº Factura</td><td style="padding:7px 10px">${d.factura_numero || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Fecha factura</td><td style="padding:7px 10px">${d.factura_fecha || '—'}</td></tr>
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold">Importe</td><td style="padding:7px 10px">${fmtImporte(d.importe_total)}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Hotel destinatario</td><td style="padding:7px 10px">${d.hotel_nombre_odoo || d.hotel_destino_factura || '—'}</td></tr>
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold">Forma de pago</td><td style="padding:7px 10px">${d.forma_pago_detalle || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Fecha recepción</td><td style="padding:7px 10px">${now}</td></tr>
</table>
${erroresHtml ? `<div style="background:#FFF7ED;border:1px solid #FED7AA;padding:12px;border-radius:4px;margin:16px 0">
  <strong>Incidencias detectadas:</strong>
  <ul style="margin:8px 0 0 0;padding-left:18px">${erroresHtml}</ul>
</div>` : ''}
${FOOT}
</body></html>`;
  acuse_subject = `${s.emoji} [Alda Hotels] Factura ${d.factura_numero || ''} — ${s.estado}`;
} else {
  // ---------- CASO VARIAS FACTURAS (resumen agregado) ----------
  const nOK    = facturas.filter(d => !d.tiene_error_grave && !d.tiene_error_leve).length;
  const nLeve  = facturas.filter(d => !d.tiene_error_grave && d.tiene_error_leve).length;
  const nGrave = facturas.filter(d => d.tiene_error_grave).length;

  const resumenPartes = [];
  if(nOK)    resumenPartes.push(`${nOK} correcta${nOK>1?'s':''}`);
  if(nLeve)  resumenPartes.push(`${nLeve} con avisos`);
  if(nGrave) resumenPartes.push(`${nGrave} en revisión`);
  const resumenTxt = resumenPartes.join(' · ');

  const bannerEmoji = nGrave ? '🔴' : (nLeve ? '🟡' : '✅');
  const bannerBg     = nGrave ? '#FEE2E2' : (nLeve ? '#FEF3C7' : '#D1FAE5');
  const bannerBorder = nGrave ? '#991B1B' : (nLeve ? '#D97706' : '#065F46');

  const filas = facturas.map((d, i) => {
    const s = estadoDe(d);
    const bg = (i % 2 === 0) ? '#ffffff' : '#f5f5f5';
    return `<tr style="background:${bg}">
      <td style="padding:7px 10px;text-align:center">${s.emoji}</td>
      <td style="padding:7px 10px">${d.factura_numero || '—'}</td>
      <td style="padding:7px 10px;text-align:right">${fmtImporte(d.importe_total)}</td>
      <td style="padding:7px 10px">${d.hotel_nombre_odoo || d.hotel_destino_factura || '—'}</td>
      <td style="padding:7px 10px;font-size:11px;color:${s.colorBorder}">${s.estado}</td>
    </tr>`;
  }).join('');

  const incidencias = facturas.map(d => {
    const errs = [
      ...((d.errores_graves)||[]).map(e => `<li style="color:#991B1B"><strong>Error:</strong> ${e}</li>`),
      ...((d.errores_leves)||[]).map(e => `<li style="color:#92400E"><strong>Aviso:</strong> ${e}</li>`)
    ];
    if(!errs.length) return '';
    return `<div style="margin:10px 0 0 0">
      <div style="font-weight:bold;font-size:12px">Factura ${d.factura_numero || '—'}</div>
      <ul style="margin:4px 0 0 0;padding-left:18px;font-size:12px">${errs.join('')}</ul>
    </div>`;
  }).filter(Boolean).join('');

  html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;font-size:13px;color:#111;padding:24px;max-width:640px;margin:0 auto">
${HEAD}
<div style="background:${bannerBg};border-left:4px solid ${bannerBorder};padding:14px 18px;border-radius:4px;margin-bottom:20px">
  <strong>${bannerEmoji} ${facturas.length} facturas recibidas</strong><br>
  <span style="font-size:12px">${resumenTxt}</span>
</div>
<p>Hemos recibido y procesado las siguientes facturas adjuntas a tu correo:</p>
<table style="width:100%;border-collapse:collapse;font-size:12px;margin:16px 0;border:1px solid #e5e7eb">
  <tr style="background:#1F2937;color:#fff">
    <td style="padding:8px 10px;text-align:center"></td>
    <td style="padding:8px 10px;font-weight:bold">Nº Factura</td>
    <td style="padding:8px 10px;font-weight:bold;text-align:right">Importe</td>
    <td style="padding:8px 10px;font-weight:bold">Hotel</td>
    <td style="padding:8px 10px;font-weight:bold">Estado</td>
  </tr>
  ${filas}
</table>
${incidencias ? `<div style="background:#FFF7ED;border:1px solid #FED7AA;padding:12px;border-radius:4px;margin:16px 0">
  <strong>Incidencias detectadas:</strong>
  ${incidencias}
</div>` : ''}
<p style="font-size:11px;color:#777;margin-top:8px">Recepción: ${now}</p>
${FOOT}
</body></html>`;
  acuse_subject = `${bannerEmoji} [Alda Hotels] ${facturas.length} facturas recibidas — ${resumenTxt}`;
}

// Item único (un solo acuse por correo). Conserva ...d de la 1ª factura para
// compatibilidad aguas abajo, pero con flags agregados (OR) para IF_Error_Leve.
const base = facturas[0] || {};
return {
  json: {
    ...base,
    tiene_error_grave: anyGrave,
    tiene_error_leve:  anyLeve,
    acuse_to: emailRemitente,
    remitente_interno: remitenteInterno,
    _from_diagnostico: _fromDiagnostico,
    acuse_subject,
    acuse_html: html,
    acuse_num_facturas: facturas.length,
    acuse_attachments: attachKeys.join(',')
  },
  binary: outBinary
};

// Restaurar PDF original + summary PDF para merge
const summaryPdf = $input.item.binary?.summary_pdf;
if (!summaryPdf) throw new Error('No se encontró summary_pdf');

// Intentar recuperar el PDF original
let originalPdf = null;

try {
  const detectItems = $('Detect_PDF_Adjunto').all();
  // Buscar por pdf_index
  const pdfIndex = $input.item.json?.pdf_index;
  if(pdfIndex && detectItems[pdfIndex - 1]){
    originalPdf = detectItems[pdfIndex - 1].binary?.attachment_0;
  }
  // Fallback: por itemIndex
  if(!originalPdf) {
    originalPdf = detectItems[Math.min($itemIndex, detectItems.length-1)]?.binary?.attachment_0;
  }
} catch(e) {
  // Silenciar error — continuar sin PDF original
}

// Diagnóstico: por qué no se encontró el PDF original, si es el caso.
let _diagPdf = '';
if(!originalPdf){
  try {
    const detectItems = $('Detect_PDF_Adjunto').all();
    _diagPdf = `pdf_index=${$input.item.json?.pdf_index} itemIndex=${$itemIndex} total_detectados=${detectItems.length} claves_disponibles=${detectItems.map(d=>Object.keys(d.binary||{}).join('|')).join(',')}`;
  } catch(e) { _diagPdf = 'error diag: ' + e.message; }
}

// _tiene_adjunto_original: condición TÉCNICA real (no el flag semántico
// solo_enlace) que decide si Merge_PDFs_Centros puede ejecutarse con
// attachment_0. Cubre tanto el caso esperado (factura solo-enlace, sin PDF)
// como cualquier otro caso en que, por lo que sea, no se pudo recuperar el
// PDF original de una factura que sí lo tenía — evita que Merge_PDFs_Centros
// reviente por falta de 'attachment_0'.
if(!originalPdf){
  return {
    json: { ...$input.item.json, _tiene_adjunto_original: false, _diag_pdf: _diagPdf },
    binary: { pdf_final: summaryPdf }
  };
}

return {
  json: { ...$input.item.json, _tiene_adjunto_original: true },
  binary: { attachment_0: originalPdf, summary_pdf: summaryPdf }
};

const d = $input.item.json;
if(!d.mover_necesario || !d.email_uid) return [{ json: { ...d, imap_movido: false } }];
const { ImapFlow } = require('imapflow');
const client = new ImapFlow({
  host: 'gestionalda.es', port: 993, secure: true,
  auth: { user: 'facturasproveedores@aldahotels.com', pass: 'AdtPr@72' },
  logger: false
});
try {
  await client.connect();
  await client.mailboxOpen('INBOX');
  await client.messageMove(String(d.email_uid), 'Requiere Revision', { uid: true });
  await client.logout();
  return [{ json: { ...d, imap_movido: true } }];
} catch(e) {
  try { await client.logout(); } catch(_) {}
  return [{ json: { ...d, imap_movido: false, imap_error: e.message } }];
}

// Mover email a carpeta Requiere Revision
const d = $('Prep_Aprobacion').item.json;
let emailUid = null;
try {
  emailUid = $('Email Trigger (IMAP)1').item.json.attributes?.uid || null;
} catch(e) {}
return [{ json: { ...d, mover_a_carpeta: 'Requiere Revision', email_uid: emailUid, mover_necesario: true } }];

// Registrar factura pendiente de aprobación en Sheets
const d = $('Prep_Aprobacion').item.json;
const now = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' });

const estadoFinal = d.tiene_error_grave ? 'Pendiente aprobación — Error grave' : 'Pendiente aprobación — Aviso leve';
const motivoRevision = [
  ...(d.errores_graves || []).map(e => 'GRAVE: ' + e),
  ...(d.errores_leves  || []).map(e => 'LEVE: '  + e)
].join('; ');

// Datos del email
let emailRemitente = '', asuntoEmail = '', nombreAdjunto = '', fechaRecepcion = now;
try {
  const trigger = $('Email Trigger (IMAP)1').item.json;
  emailRemitente = trigger.from?.value?.[0]?.address || trigger.from?.address || String(trigger.from || '');
  asuntoEmail = trigger.subject || '';
  fechaRecepcion = trigger.date
    ? new Date(trigger.date).toLocaleString('es-ES', { timeZone: 'Europe/Madrid' })
    : now;
} catch(e) {}

return [{
  json: {
    hotel_destino:         d.hotel_destino_factura || '',
    sociedad_destino:      d.sociedad || '',
    fecha_recepcion:       fechaRecepcion,
    email_remitente:       emailRemitente,
    asunto_email:          asuntoEmail,
    nombre_adjunto:        d.drive_file_name || '',
    fecha_ocr:             now,
    factura_numero:        d.factura_numero || '',
    proveedor:             d.proveedor_nombre || '',
    factura_fecha:         d.factura_fecha || '',
    importe_total:         d.importe_total ?? '',
    forma_pago_detectada:  d.forma_pago_detalle || '',
    hotel_odoo:            d.hotel_nombre_odoo || '',
    sociedad:              d.sociedad || '',
    codigo_hotel:          String(d.codigo_hotel || ''),
    nivel_validacion:      d.validacion?.nivel ?? 0,
    metodo_identificacion: d.validacion?.mensaje || '',
    fecha_docuware:        '—',
    dw_hotel:              d.dw_hotel || '',
    dw_fpago:              d.dw_fpago || '',
    resultado_docuware:    'Pendiente aprobación',
    estado_final:          estadoFinal,
    motivo_revision:       motivoRevision,
    carpeta_imap:          'Requiere Revision',
    fecha_fin:             now,
    drive_file_id:         d.drive_file_id || ''
  }
}];

// Preparar datos para email de aprobación
const d = $('Build_HTML_Centros').item.json;
const now = new Date();
// Token simple — los datos van directamente en la URL como parámetros
const emailUid = $('Email Trigger (IMAP)1').item.json.attributes?.uid || '';
const token = `${(d.factura_numero || 'SIN').replace(/[^a-zA-Z0-9]/g,'_')}_${emailUid}`;
const dw_hotel_enc = encodeURIComponent(d.dw_hotel || 'PENDIENTE');
const dw_fpago_enc = encodeURIComponent(d.dw_fpago || '00');
const factura_enc  = encodeURIComponent(d.factura_numero || '');
const proveedor_enc = encodeURIComponent((d.proveedor_nombre || '').substring(0, 50));

const email_uid = $('Email Trigger (IMAP)1').item.json.attributes?.uid || $('Email Trigger (IMAP)1').item.json.uid || '';
const uid_enc = encodeURIComponent(email_uid);
const nota_enc = encodeURIComponent((d.dw_nota || '').substring(0,50));
const nota2_enc = encodeURIComponent((d.dw_nota2 || d.factura_numero || '').substring(0,50));
const webhookUrl  = `https://n8n.gestionalda.es/webhook/aprobar-factura?token=${token}&hotel=${dw_hotel_enc}&fpago=${dw_fpago_enc}&factura=${factura_enc}&proveedor=${proveedor_enc}&uid=${uid_enc}&nota=${nota_enc}&nota2=${nota2_enc}`;
const rechazarUrl = `https://n8n.gestionalda.es/webhook/aprobar-factura?token=${token}&accion=rechazar&factura=${factura_enc}`;

// Construir HTML del email
const esGrave = true; // Solo llegan graves aquí
const colorHeader = '#991B1B';
const bgHeader    = '#FEE2E2';
const emoji       = '🔴';
const motivo = d.motivo_revision || '';
const tipoError = motivo === 'factura_dirigida_a_sociedad'
  ? 'Factura a sociedad — imputación manual requerida'
  : motivo === 'multiples_centros'
  ? 'Múltiples centros — asignar manualmente'
  : 'Error grave — revisión obligatoria';

const listaGraves = (d.errores_graves || []).map(e => `<li>${e}</li>`).join('');
const listaLeves  = (d.errores_leves  || []).map(e => `<li>${e}</li>`).join('');

const htmlEmail = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;font-size:13px;color:#111;padding:24px;max-width:620px;margin:0 auto">
<div style="background:${colorHeader};color:#fff;padding:14px 18px;border-radius:6px;margin-bottom:20px">
  <strong>${emoji} ${tipoError}</strong>
</div>
<table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:16px">
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold;width:35%">Proveedor</td><td style="padding:7px 10px">${d.proveedor_nombre || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Nº Factura</td><td style="padding:7px 10px">${d.factura_numero || '—'}</td></tr>
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold">Fecha</td><td style="padding:7px 10px">${d.factura_fecha || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Importe</td><td style="padding:7px 10px">${d.importe_total != null ? d.importe_total + ' €' : '—'}</td></tr>
  <tr style="background:#f5f5f5"><td style="padding:7px 10px;font-weight:bold">Hotel</td><td style="padding:7px 10px">${d.hotel_nombre_odoo || d.hotel_destino_factura || '—'}</td></tr>
  <tr><td style="padding:7px 10px;font-weight:bold">Sociedad</td><td style="padding:7px 10px">${d.sociedad || '—'}</td></tr>
</table>
${listaGraves ? `<div style="background:#FEE2E2;border-left:4px solid #991B1B;padding:12px;margin-bottom:12px;border-radius:3px"><strong>Errores graves:</strong><ul style="margin:6px 0 0 0;padding-left:18px">${listaGraves}</ul></div>` : ''}
${listaLeves  ? `<div style="background:#FEF3C7;border-left:4px solid #D97706;padding:12px;margin-bottom:20px;border-radius:3px"><strong>Avisos leves:</strong><ul style="margin:6px 0 0 0;padding-left:18px">${listaLeves}</ul></div>` : ''}
<div style="text-align:center;margin:28px 0 16px">
  <a href="${webhookUrl}" style="background:#065F46;color:#fff;padding:14px 36px;text-decoration:none;border-radius:6px;font-size:15px;font-weight:bold;display:inline-block;margin-right:12px">✓ Aprobar y archivar</a>
  <a href="${rechazarUrl}" style="background:#7F1D1D;color:#fff;padding:14px 36px;text-decoration:none;border-radius:6px;font-size:15px;font-weight:bold;display:inline-block">✗ Rechazar</a>
</div>
<p style="font-size:11px;color:#999;text-align:center;margin-top:24px">Sistema de facturación Alda Hotels · ${now.toLocaleString('es-ES',{timeZone:'Europe/Madrid'})}</p>
</body></html>`;

// Datos de Google Drive
const driveFileId = $('Drive_Subir_PDF').item.json?.id || '';
const driveFileName = $('Drive_Subir_PDF').item.json?.name || '';

return [{
  json: {
    drive_file_id: driveFileId,
    drive_file_name: driveFileName,
