// Consolida datos de referencia en un único item para validación aguas abajo.
// - Compañías (res.company): se leen por referencia de Get_Companies.
// - Códigos postales (res.city.zip): llegan como input de este nodo (Get_CityZip).
//   En res.city.zip: name = C.P. y city_id = [id, nombre de ciudad].
// Se une cada compañía con su registro de res.city.zip para obtener el CP y la
// ciudad autoritativos. Detect_PDF_Adjunto lee el email del trigger, no de este
// item, así que consolidar aquí es seguro.

const companiesRaw = $('Get_Companies').all().map(i => i.json);

// Registros de res.city.zip. Dos índices para unir de forma robusta:
//  - por id (para el caso en que res.company tenga zip_id → res.city.zip)
//  - por CP normalizado (name), para unir por el código postal de texto
const zips = $input.all().map(i => i.json);
const zipById = {};
const zipByCp = {};
for (const z of zips) {
  if (!z) continue;
  const ciudad = Array.isArray(z.city_id) ? z.city_id[1] : '';
  const rec = { cp: z.name || '', ciudad };
  if (z.id != null) zipById[z.id] = rec;
  if (z.name) zipByCp[String(z.name).trim()] = rec;
}

const companies = companiesRaw.map(comp => {
  let rec = null;
  // 1) clave directa: res.company.zip_id → res.city.zip
  if (Array.isArray(comp.zip_id) && zipById[comp.zip_id[0]]) rec = zipById[comp.zip_id[0]];
  // 2) fallback: emparejar por el CP de texto de la compañía
  if (!rec && comp.zip && zipByCp[String(comp.zip).trim()]) rec = zipByCp[String(comp.zip).trim()];
  const ciudad = (rec && rec.ciudad) || (Array.isArray(comp.city_id) ? comp.city_id[1] : comp.city) || '';
  const cp = (rec && rec.cp) || comp.zip || '';
  return { ...comp, ciudad, cp };
});

