});

// Leer datos de la factura
// Merge_Final combina: [in0] item factura + [in1] item con hoteles embebidos
// Detectar cuál es cuál por contenido
// Mapa de sociedades → costes generales
var COSTES_GENERALES = [
  { sociedad: 'hoteles rias altas',       codigo: '400', nombre: 'Costes Generales Hoteles Rías Altas, S.L.U.' },
  { sociedad: 'alda compostela',          codigo: '100', nombre: 'Costes Generales Alda Compostela S.L.U.' },
  { sociedad: 'alda castilla',            codigo: '200', nombre: 'Costes Generales Alda Castilla, S.L.' },
  { sociedad: 'alda rias baixas',         codigo: '300', nombre: 'Costes Generales Alda Rías Baixas S.L.U.' },
  { sociedad: 'alda hotels hosteleria',   codigo: '500', nombre: 'Costes Generales Alda Hotels Hostelería S.L' },
  { sociedad: 'consultores hoteleros',    codigo: '012', nombre: 'Coste General Consultores Hoteleros Integrales' },
