  { sociedad: 'restauradores de comida',  codigo: '800', nombre: 'Coste general Restauradores de Comida Atlántica' },
];

// Datos de la factura vienen directamente de IF_Datos_Extraidos
const datosIA = $input.item.json;
const soloEnlace = datosIA.solo_enlace === true;

// ── Leer el CUERPO del email (para detectar 'efectivo' y avisos de revisión) ──
let cuerpoEmail = '';
try {
  const t = $('Email Trigger (IMAP)1').first().json;
