} catch(e) {}
// Efectivo indicado en el cuerpo del mensaje (BUG: antes solo se miraba la factura)
const efectivoEnCuerpo = /\befectivo\b|\bmetalico\b|\bmetálico\b|\ben mano\b|\bcontra ?reembolso\b/.test(cuerpoEmail);
// El cuerpo pide revisión manual explícita
const CUERPO_REVISION_KW = ['revisar', 'revision', 'revisión', 'urgente', 'incidencia', 'reclamacion', 'reclamación', 'error en la factura', 'factura incorrecta', 'abono', 'rectificativa', 'duplicad'];
const cuerpoRequiereAtencion = CUERPO_REVISION_KW.some(k => cuerpoEmail.includes(k));
const enlaceDescarga = datosIA.enlace_descarga || null;
const enlacesDetectados = datosIA.enlaces_detectados || [];
// Hoteles desde Code_Hoteles_JSON (upstream secuencial)
let hoteles = [];
try { hoteles = $('Code_Hoteles_JSON').first().json.hoteles_odoo.map(h => ({ json: h })); } catch(e) {}

const EMAILS_GENERICOS = ['info@insidehome.es'];
const WHITELIST = ['diegovieiros@aldahotels.com'];
