// Registros que no son hoteles reales
const EXCLUIR_NOMBRES = ['costes generales', 'coste general', 'consultores hoteleros',
                          'garfo e coitelo', 'gestion proyectos', 'taberna central',
                          'a nosa taberna', 'niuco homes', 'restauradores de comida'];

// Sociedades — si hotel_destino coincide y no hay match por email → revisión manual
const SOCIEDADES_CONOCIDAS = [
  'hoteles rias altas', 'alda compostela', 'alda castilla', 'alda rias baixas',
  'alda hotels hosteleria', 'consultores hoteleros integrales', 'consultores hoteleros integral', 'niuco homes',
  'restauradores de comida atlantica', 'alda hotels'
];

let emailRemitente = '';
let asuntoEmail = '';
try {
  const t = $('Email Trigger (IMAP)1').first().json;
  emailRemitente = (t.from?.value?.[0]?.address || t.from?.address || t.from || '').toLowerCase().trim();
  asuntoEmail = t.subject || '';
} catch(e) {}

const normalizar = t => String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/ +/g,' ').trim();
const extraerCP  = t => (String(t||'').match(/\b\d{5}\b/)||[null])[0];
const bigramas   = s => { const set=new Set(),n=normalizar(s); for(let i=0;i<n.length-1;i++)set.add(n.slice(i,i+2)); return set; };
const jaccard    = (a,b) => { const sa=bigramas(a),sb=bigramas(b); if(!sa.size||!sb.size)return 0; let inter=0; for(const bg of sa)if(sb.has(bg))inter++; return inter/(sa.size+sb.size-inter); };

const esCosteGeneral = nombre => EXCLUIR_NOMBRES.some(k => normalizar(nombre||'').includes(k));
const esSociedad = nombre => SOCIEDADES_CONOCIDAS.some(k => normalizar(nombre||'').includes(k));
const esEmailAlda = email => email && email.endsWith(DOMINIO_ALDA) && !EMAILS_GENERICOS.includes(email);

const emailBusqueda = (datosIA.usuario_envio||'').toLowerCase().trim();
const dirFactura    = datosIA.hotel_direccion||'';
const cpFactura     = extraerCP(dirFactura);
const nombreDestino = normalizar(datosIA.hotel_destino||'');

let mejorMatch = null, nivelSeguridad = 0, motivoLog = 'Sin coincidencia', scoreDir = 0;
let modoMultiplesCentros = false;
let esCostesGenerales = false;
let matchSociedad = true;
let motivoRevision = '';

// ============================================================
// PASO 0: La IA identificó el hotel directamente (codigo_hotel_ia)
// Validación OBLIGATORIA de sociedad: si el hotel sugerido pertenece a una
// sociedad que no comparte ninguna palabra significativa con el destinatario
// de la factura, SE RECHAZA el match sin excepciones (ni siquiera con
// confianza alta — una dirección puede matchear "bien" por error de
// extracción, pero la sociedad es un dato legal fiable que no debe saltarse).
// ============================================================
// ── GUARDARRAÍL DE SOCIEDAD POR CIF ──────────────────────────────────────
// La sociedad identificada por el CIF de la factura (calculada en
// Match_Hotel_Determinista, campo sociedad_cif_id) es la autoridad. NINGÚN
// paso de matching de este nodo puede elegir un hotel que no pertenezca a esa
// sociedad. Se enlaza por id de compañía (infalible). Si no hay CIF utilizable,
// _hotelSociedadOk no filtra (deja pasar) y se cae al comportamiento por texto.
const _socCifId = datosIA.sociedad_cif_id ?? null;
const _socCifNombre = datosIA.sociedad_cif_nombre || '';
const _GENSOC = new Set(['alda','hotel','hoteles','sociedad','limitada','anonima','unipersonal','slu','sau','sl','sa']);
const _sigWordsSoc = s => normalizar(s).split(' ').filter(w => w.length >= 4 && !_GENSOC.has(w));
// Hoteles con el enlace de sociedad (company_odoo_id) roto o ausente en Odoo —
// se recogen aquí para poder avisar de un problema de DATOS, no solo aplicar
// el guardarraíl. El código puede compensar con el fallback de texto, pero la
// ficha del hotel en Odoo debería tener el enlace correcto.
const _hotelesSinEnlaceSociedad = [];
function _hotelSociedadOk(hj){
  if(_socCifId == null) return true;               // sin CIF fiable → no filtra aquí
  if(hj.company_odoo_id == null){
    _hotelesSinEnlaceSociedad.push(hj.nombre_limpio || hj.codigo_hotel || '?');
    // Sin id de compañía: NO dejamos pasar a ciegas. Fallback por texto de la
    // sociedad (igual que hace el guardarraíl en Match_Hotel_Determinista) —
    // si el texto tampoco coincide, se bloquea igual que con id.
    const wh = new Set(_sigWordsSoc(hj.sociedad || ''));
    for (const w of _sigWordsSoc(_socCifNombre)) if (wh.has(w)) return true;
    return false;
  }
  return String(hj.company_odoo_id) === String(_socCifId);
}
const _socDestinatario = normalizar(datosIA.destinatario_razon_social || datosIA.hotel_destino || '');
if(datosIA.codigo_hotel_ia){
  const codigoRaw = String(datosIA.codigo_hotel_ia).trim();
  if(/^\d+$/.test(codigoRaw)){
    const codigoIA = codigoRaw.padStart(3,'0');
    const hotelIA = hoteles.find(h => String(h.json.codigo_hotel||'').padStart(3,'0') === codigoIA);
    if(hotelIA){
      const _socHotel = normalizar(hotelIA.json.sociedad || '');
      const _generic = new Set(['alda','hotel','hoteles','sociedad','limitada','anonima','unipersonal','slu','sau']);
      const _wDest = _socDestinatario.split(' ').filter(w=>w.length>=4 && !_generic.has(w));
      const _wHotel = new Set(_socHotel.split(' ').filter(w=>w.length>=4 && !_generic.has(w)));
      const _sharedSig = _wDest.filter(w=>_wHotel.has(w)).length;
      const _allWDest = _socDestinatario.split(' ').filter(w=>w.length>=3);
      const _allWHotel = new Set(_socHotel.split(' ').filter(w=>w.length>=3));
      const _sharedAll = _allWDest.filter(w=>_allWHotel.has(w)).length;
      // Sociedad OK: si conocemos la sociedad por CIF, se exige que el hotel
      // pertenezca a esa compañía (enlace por id). Si no hay CIF, se cae a la
      // comparación por texto de la razón social.
      const _socOk = (_socCifId != null)
        ? _hotelSociedadOk(hotelIA.json)
        : (_sharedSig >= 1 || _sharedAll >= 2);
      if(_socOk){
        mejorMatch = hotelIA.json; nivelSeguridad = 3;
        motivoLog = 'IA identificó hotel: ' + hotelIA.json.nombre_limpio + ' (código ' + codigoIA + ')';
      }
      // Si la sociedad no coincide -> match RECHAZADO sin excepciones, deja
      // fluir a P1/P2/P3 (P3 asignará costes generales de la sociedad correcta)
    }
  }
  if(!mejorMatch){
    const nombreIA = normalizar(datosIA.codigo_hotel_ia).replace(/ /g,'');
    let mjScore = 0;
    for(const h of hoteles){
      if(esCosteGeneral(h.json.nombre_completo||'')) continue;
      if(!_hotelSociedadOk(h.json)) continue;
      const s = jaccard(nombreIA, normalizar(h.json.nombre_limpio||'').replace(/ /g,''));
      if(s > 0.5 && s > mjScore){ mjScore = s; mejorMatch = h.json; nivelSeguridad = 3; motivoLog = 'IA código texto → ' + h.json.nombre_limpio; }
    }
  }
}

// P0: Email remitente del grupo Alda
if(!mejorMatch && esEmailGrupo(emailRemitente)){
  for(const h of hoteles){
    if(esCosteGeneral(h.json.nombre_completo||'')) continue;
    if(!_hotelSociedadOk(h.json)) continue;
    const eo = String(h.json.email||'').toLowerCase();
    if(!eo || EMAILS_GENERICOS.includes(eo)) continue;
    if(eo === emailRemitente){ mejorMatch = h.json; nivelSeguridad = 3; motivoLog = 'Email remitente coincide con hotel Odoo'; break; }
  }
}

// P1: Email en la factura
if(!mejorMatch && emailBusqueda){
  for(const h of hoteles){
    if(esCosteGeneral(h.json.nombre_completo||'')) continue;
    if(!_hotelSociedadOk(h.json)) continue;
    const eo = String(h.json.email||'').toLowerCase();
    if(!eo || EMAILS_GENERICOS.includes(eo)) continue;
    if(eo === emailBusqueda){ mejorMatch = h.json; nivelSeguridad = 3; motivoLog = 'Email factura coincide con Odoo'; break; }
  }
}

// P2: Nombre del hotel en el concepto de la factura
if(!mejorMatch && datosIA.concepto){
  const conceptoNorm = normalizar(datosIA.concepto);
  let mjScore = 0;
  for(const h of hoteles){
    if(esCosteGeneral(h.json.nombre_completo||'')) continue;
    if(!_hotelSociedadOk(h.json)) continue;
    const nombreH = normalizar(h.json.nombre_limpio||'');
    if(nombreH.length < 5) continue;
    if(conceptoNorm.includes(nombreH)){ mejorMatch = h.json; nivelSeguridad = 2; motivoLog = 'Hotel en concepto: ' + h.json.nombre_limpio; break; }
    const s = jaccard(conceptoNorm, nombreH);
    if(s > 0.5 && s > mjScore){ mjScore = s; mejorMatch = h.json; nivelSeguridad = 2; motivoLog = 'Hotel en concepto (fuzzy): ' + h.json.nombre_limpio; }
  }
}

// P3: Sociedad → costes generales (siempre requiere revisión)
if(!mejorMatch && esSociedad(datosIA.hotel_destino||'')){
  const _socNorm = normalizar(datosIA.hotel_destino||'');
  const _cgMatch = COSTES_GENERALES.find(cg => _socNorm.includes(cg.sociedad));
  if(_cgMatch){
    mejorMatch = { odoo_id: null, codigo_hotel: _cgMatch.codigo, nombre_limpio: _cgMatch.nombre, nombre_completo: _cgMatch.nombre, sociedad: _cgMatch.nombre, email: '', direccion_odoo: '', cif_odoo: '' };
    esCostesGenerales = true; nivelSeguridad = 2;
    motivoLog = 'Sociedad → costes generales: ' + _cgMatch.nombre;
    motivoRevision = 'factura_dirigida_a_sociedad';
  } else {
    motivoLog = 'Factura a sociedad sin match en costes generales';
  }
}

// P4: Múltiples centros → costes generales de la sociedad
if(datosIA.multiples_centros === true){
  modoMultiplesCentros = true;
  let cgSoc = null;
  if(datosIA.hotel_destino){ const n = normalizar(datosIA.hotel_destino); cgSoc = COSTES_GENERALES.find(cg => n.includes(cg.sociedad)); }
  if(!cgSoc && mejorMatch?.sociedad){ const n = normalizar(mejorMatch.sociedad); cgSoc = COSTES_GENERALES.find(cg => n.includes(cg.sociedad)); }
  if(cgSoc){
    mejorMatch = { odoo_id: null, codigo_hotel: cgSoc.codigo, nombre_limpio: cgSoc.nombre, nombre_completo: cgSoc.nombre, sociedad: cgSoc.nombre, email: '', direccion_odoo: '', cif_odoo: '' };
    esCostesGenerales = true; nivelSeguridad = 2;
    motivoLog = 'Múltiples centros → ' + cgSoc.nombre;
    motivoRevision = 'multiples_centros';
  }
}


const erroresGraves = [];
const erroresLeves  = [];

const codigoHotelDW = mejorMatch?.codigo_hotel != null ? String(mejorMatch.codigo_hotel).padStart(3, '0') : null;

// Validación y forzado de revisión si termina cayendo en un código de Costes Generales
// Costes generales: no forzar error grave

if(datosIA.confianza_hotel === 'baja' && mejorMatch && !COSTES_GENERALES.some(cg => cg.codigo === codigoHotelDW)){
  erroresLeves.push('Identificación del hotel con confianza baja — verificar hotel destino');
}

if(!datosIA.factura_numero) erroresGraves.push('Falta número de factura');
if(!datosIA.factura_fecha)  erroresGraves.push('Falta fecha de factura');

if(!datosIA.hotel_destino)  erroresGraves.push('Falta denominación social del destinatario');
if(!datosIA.hotel_direccion && !datosIA.direccion_instalacion) erroresGraves.push('Falta dirección del destinatario');

const cifFactura = (datosIA.hotel_destino_cif || '').replace(/[^A-Z0-9]/gi,'').toUpperCase();
const cifOdoo    = (mejorMatch?.cif_odoo || '').replace(/[^A-Z0-9]/gi,'').toUpperCase();
if(cifFactura && cifOdoo && cifFactura !== cifOdoo && !COSTES_GENERALES.some(cg => cg.codigo === codigoHotelDW)) erroresGraves.push('CIF del destinatario no coincide con Odoo');

// (Comprobación de dirección fiscal duplicada eliminada — comparaba la
// dirección fiscal de la factura, que es SIEMPRE la sede social por diseño,
// contra la dirección del HOTEL concreto asignado, que es un edificio
// distinto. Esas dos direcciones son DIFERENTES por naturaleza en casi todas
// las facturas legítimas, así que este chequeo saltaba casi siempre sin
// aportar señal real. La comprobación correcta y tolerante — que compara
// contra la sede social O cualquier dirección de hotel conocida — sigue más
// abajo en este mismo nodo.)

// FALLO DE EXTRACCIÓN (parser_error): la respuesta de la IA no se pudo parsear
// como JSON. Esto NO significa que la factura esté incompleta — casi seguro
// significa que la llamada a Gemini falló, devolvió texto no-JSON, o se cortó.
// Si no distinguimos este caso, el usuario ve una cascada confusa de "falta
// nombre, falta CIF, falta importe..." para una factura que en realidad tiene
// todos esos datos perfectamente legibles — la causa real queda oculta.
if(datosIA.parser_error === true){
  erroresGraves.length = 0;
  erroresLeves.length = 0;
  const esTruncado = datosIA.truncado === true;
  erroresGraves.push(
    (esTruncado
      ? 'FALLO DE EXTRACCIÓN (respuesta truncada): la respuesta de la IA se cortó a mitad ' +
        '(corte de red/conexión durante la transmisión, no un fallo de la IA generando el ' +
        'contenido). No es que falten datos en la factura. Solución: reenviar este correo ' +
        'para que se reprocese — casi siempre basta con un segundo intento.'
      : 'FALLO DE EXTRACCIÓN: la IA no devolvió un JSON válido para esta factura (' +
        (datosIA.error_msg || 'motivo desconocido') + '). No es que falten datos en la ' +
        'factura — es un fallo técnico de la llamada a la IA. Reintentar el procesamiento; ' +
        'si persiste, revisar OpenRouter_Vision_Call.'
    ) +
    (datosIA.raw_text ? ' Fragmento de respuesta recibida: "' + String(datosIA.raw_text).slice(0,150) + '..."' : '')
  );
}

// Todas las comprobaciones de campos individuales se OMITEN por completo si ya
// sabemos que la extracción falló (parser_error) — no tiene sentido decir "falta
// el nombre, falta el CIF, falta el importe..." cuando el problema real es que la
// IA no devolvió un JSON legible. El mensaje de FALLO DE EXTRACCIÓN de arriba ya
// es la única incidencia relevante en ese caso.
if(!datosIA.parser_error){
  if(!datosIA.proveedor_nombre)    erroresGraves.push('Falta nombre del proveedor');
  if(!datosIA.proveedor_cif)       erroresGraves.push('Falta CIF/NIF del proveedor');
  if(!datosIA.proveedor_direccion) erroresGraves.push('Falta dirección del proveedor');

  if(!datosIA.importe_total && datosIA.importe_total !== 0) erroresGraves.push('Falta total de factura');
  if(!datosIA.base_imponible && datosIA.base_imponible !== 0) erroresGraves.push('Falta base imponible');

  // LEVE (spec escala de errores): no consta el % de IVA desglosado
  const _tieneIvaPct = Array.isArray(datosIA.iva_desglose) &&
    datosIA.iva_desglose.some(i => i && (i.tipo != null && i.tipo !== '' || (i.cuota != null && i.cuota !== '')));
  if(!_tieneIvaPct){
    erroresLeves.push('No consta el porcentaje/desglose de IVA en la factura — verificar (se calcula en el futuro)');
  }

  if(!datosIA.concepto && !datosIA.direccion_instalacion) erroresGraves.push('Falta concepto/descripción');

  if(!mejorMatch){
    erroresGraves.push('No se ha podido identificar el hotel/sociedad destinatario');
  }
  if(mejorMatch && !matchSociedad && !datosIA.direccion_instalacion && !COSTES_GENERALES.some(cg => cg.codigo === codigoHotelDW)){
    erroresGraves.push('El hotel no coincide con la sociedad de la factura');
  }

  // LEVE (no bloquea): la direccion fiscal de la SOCIEDAD en la factura no coincide
  // con la registrada en Odoo (res.company). Detecta domicilios desactualizados.
  // Se busca la compañia por CIF; aplica con cualquier metodo de match.
  try {
    const normCif = s => String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'').replace(/^ES/,'');
    const companies = ($('Code_Companies_JSON').first().json.companies) || [];
    const cifFac = normCif(datosIA.hotel_destino_cif || datosIA.destinatario_cif);
    const dirFiscalFac = datosIA.hotel_direccion || (datosIA.direccion_fiscal && datosIA.direccion_fiscal.raw) || '';
    if(cifFac && dirFiscalFac && companies.length){
      const comp = companies.find(c => normCif(c.vat) === cifFac);
      if(comp){
        // CP y ciudad autoritativos: vienen de res.city (unidos en Code_Companies_JSON
        // como comp.cp y comp.ciudad). Fallback a los campos de res.company.
        const cpComp = comp.cp || comp.zip || '';
        const ciudadComp = comp.ciudad || (Array.isArray(comp.city_id) ? comp.city_id[1] : (comp.city || ''));
        const dirComp = [comp.street, comp.street2, cpComp, ciudadComp].filter(Boolean).join(' ');
        if(dirComp){
          // La dirección fiscal de la factura NO se considera errónea si coincide con
          // la sede social (res.company) O con cualquier dirección de hotel del grupo:
          // los proveedores usan legítimamente la dirección de un hotel como domicilio
          // de la factura. Solo se marca leve si no coincide con NINGUNA dirección Alda
          // conocida (dato realmente ajeno/desactualizado).
          const dirFacNorm = normalizar(dirFiscalFac);
          let mejorSim = jaccard(dirFacNorm, normalizar(dirComp));
          try {
            for (const h of hoteles) {
              const hj = h.json || h;
              const dh = hj.direccion_odoo || hj.contact_address_complete || '';
              if (dh) mejorSim = Math.max(mejorSim, jaccard(dirFacNorm, normalizar(dh)));
            }
          } catch(e) {}
          if(mejorSim < 0.45){
            erroresLeves.push('Direccion fiscal de la factura no coincide con ninguna direccion Alda conocida (sede o hoteles): factura="'+dirFiscalFac+'" — verificar');
          }
        }
      }
    }
  } catch(e){}
