// NOTA: la creación automática de la carpeta destino (mailboxCreate) se quitó
// deliberadamente de aquí. Crear una carpeta que YA EXISTE puede dejar la
// conexión IMAP en un estado inconsistente para el comando MOVE que viene justo
// después, rompiendo el movimiento incluso a carpetas que antes funcionaban.
// Es un problema de configuración de una sola vez: las carpetas deben existir
// de antemano en el servidor de correo (Procesadas, Requiere Revision, Subido
// con Revision Necesaria) — no algo que deba arriesgarse en cada ejecución.
try {
  await client.connect();
  await client.mailboxOpen('INBOX');
  await client.messageMove(String(uid), carpeta, { uid: true });
  await client.logout();
  return [{ json: { resultado: `Email ${uid} movido a ${carpeta}`, carpeta, uid } }];
} catch(e) {
  try { await client.logout(); } catch(_) {}
  // Diagnóstico explícito: si la carpeta no existe, el mensaje de imapflow suele
  // incluir 'NONEXISTENT' o 'TRYCREATE'. Se deja visible tal cual para poder
  // distinguir "no existe la carpeta" de otros fallos (auth, red, etc.).
  return [{ json: { resultado: 'Error: ' + e.message, uid, carpeta, error_detalle: String(e.responseText || e.response || '') } }];
}

