const items = $input.all();
const results = [];

for (let _idx = 0; _idx < items.length; _idx++) {
  const item = items[_idx];
  let raw = item.json.output || item.json.text || item.json.content || '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);

  let parsed = null;
  let errorMsg = null;

  try {
    // 1. Eliminar bloques markdown ```json ... ``` o ``` ... ```
    let clean = raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();

    // 2. Extraer desde { hasta el último }
    const start = clean.indexOf('{');
    const end = clean.lastIndexOf('}');
    if (start >= 0 && end > start) {
      clean = clean.slice(start, end + 1);
    }

    // 3. Limpiar caracteres de control (excepto \n \r \t en strings)
    clean = clean.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ');

    parsed = JSON.parse(clean);
    parsed.parser_error = false;

  } catch (e) {
    errorMsg = e.message;

    // Intento de rescate: regex para extraer campos clave
    try {
      const rescue = {};
      const fields = [
        'proveedor_nombre','proveedor_cif','factura_numero','factura_fecha',
        'hotel_destino','importe_total','base_imponible','codigo_hotel_ia'
      ];
      for (const f of fields) {
        const m = raw.match(new RegExp('"' + f + '"\\s*:\\s*"([^"]*)"'));
        if (m) rescue[f] = m[1];
        const mNum = raw.match(new RegExp('"' + f + '"\\s*:\\s*([0-9.]+)'));
        if (mNum) rescue[f] = parseFloat(mNum[1]);
      }
      if (Object.keys(rescue).length > 0) {
        const _abre = (raw.match(/\{/g) || []).length;
        const _cierra = (raw.match(/\}/g) || []).length;
        rescue.parser_error = true;
        rescue.truncado = _abre > _cierra;
        rescue.error_msg = (rescue.truncado ? 'Respuesta de la IA truncada/incompleta (posible corte de red). ' : '') +
                            'JSON parcialmente recuperado (' + Object.keys(rescue).filter(k=>!['parser_error','truncado','error_msg'].includes(k)).length + ' campos): ' + errorMsg;
        rescue.raw_text = raw.substring(0, 400);
        parsed = rescue;
      }
    } catch(e2) {}
  }

  if (!parsed) {
    // Detectar específicamente TRUNCAMIENTO: la respuesta parece un JSON válido
    // que se cortó a mitad (llaves/comillas sin cerrar), distinto de un JSON
    // simplemente mal formado. Esto apunta a un corte de red/conexión durante
    // la respuesta (HTTP 200 pero cuerpo incompleto) — no a un error de la IA
    // generando el contenido, así que conviene distinguirlo en el diagnóstico.
    const abre = (raw.match(/\{/g) || []).length;
    const cierra = (raw.match(/\}/g) || []).length;
    const comillasAbiertas = (raw.match(/(?<!\\)"/g) || []).length % 2 !== 0;
    const pareceTruncado = abre > cierra || comillasAbiertas;
    parsed = {
      parser_error: true,
      truncado: pareceTruncado,
      error_msg: (pareceTruncado ? 'Respuesta de la IA truncada/incompleta (posible corte de red a mitad de transmisión). ' : '') +
                 (errorMsg || 'No se pudo parsear el JSON de la IA'),
      raw_text: raw.substring(0, 400)
    };
  }

  results.push({ json: { ...item.json, ...parsed }, binary: item.binary, pairedItem: { item: _idx } });
}

return results;

// =====================================================================
// Match_Hotel_Determinista
// Insertar:  Parser_JSON_Centros -> [ESTE NODO] -> IF_Datos_Extraidos
//
// Match hotel<->Odoo determinista, priorizando la dirección de
// INSTALACIÓN sobre la fiscal. Sobrescribe codigo_hotel_ia y
// confianza_hotel para que Build_HTML_Centros (PASO 0) lo consuma.
//
// IMPORTANTE: Code_Hoteles_JSON viene de Clean_Address, que renombra
// los campos -> codigo_hotel, direccion_odoo, nombre_limpio, sociedad.
// Se normaliza tolerando ambos esquemas.
// =====================================================================

const datos = { ...$input.item.json };
datos.codigo_hotel_ia_original = $input.item.json.codigo_hotel_ia ?? null; // para diagnóstico

// Descartar documentos que NO son factura (presupuesto/oferta/albaran/proforma).
// Anulamos factura_numero para que IF_Datos_Extraidos los filtre y no se procesen
// ni archiven ni generen fila en Sheets. Evita el doble procesado por email
// con factura + presupuesto como adjuntos separados.
if (datos.es_factura === false) {
  return { json: { ...datos, factura_numero: null, descartado_motivo: 'no_es_factura' }, binary: $input.item.binary };
}


// ---------- Normalizar hoteles (tolerante a esquema crudo o limpio) ----------
let rawHoteles = [];
try { rawHoteles = $('Code_Hoteles_JSON').first().json.hoteles_odoo || []; } catch (e) {}

const norm = t => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/ +/g, ' ').trim();

const EXCLUIR_CG = ['costes generales', 'coste general', 'consultores hoteleros',
  'garfo', 'taberna', 'gestion proyectos', 'niuco', 'restauradores'];

const HOTELES = rawHoteles.map(h => ({
  codigo:    h.codigo_hotel || h.pms_property_code || null,
  direccion: h.direccion_odoo || h.contact_address_complete || '',
  nombre:    h.nombre_limpio || h.nombre_completo || h.name || '',
  sociedad:  h.sociedad || (Array.isArray(h.company_id) ? h.company_id[1] : '') || '',
  company_odoo_id: h.company_odoo_id ?? (Array.isArray(h.company_id) ? h.company_id[0] : null),
  email:     h.email || ''
})).filter(h => h.codigo && h.direccion && !EXCLUIR_CG.some(k => norm(h.nombre).includes(k)));

// ---------- Parsing / scoring de direcciones ----------
const PROV_STOP = new Set(['coruna','la','lugo','ourense','pontevedra','espana','spain','provincia','aprox']);
const VIA_STOP  = new Set(['cl','c','calle','rua','r','av','avda','avenida','pz','plaza','pl','pza','ps',
  'paseo','tr','travesia','cr','carretera','ctra','urb','urbanizacion','de','del','la','el','los','las',
  'n','num','numero','s','bajo','sn','b','lugar','barrio','poligono','pol']);

function parseDir(raw) {
  const n = norm(raw);
  const cp = (n.match(/\b\d{5}\b/) || [null])[0];
  const nums = (n.match(/\b\d{1,4}\b/g) || []).filter(x => x !== cp);
  const numero = nums.length ? nums[nums.length - 1] : null;
  const tokens = new Set(
    n.split(' ').filter(w => w.length >= 3 && !VIA_STOP.has(w) && !PROV_STOP.has(w) && !/^\d+$/.test(w))
  );
  return { raw: n, cp, numero, tokens };
}
function dirToRaw(d) {
  if (!d) return '';
  if (typeof d === 'string') return d;
  if (d.raw) return d.raw;
  return [d.via, d.municipio, d.cp, d.provincia].filter(Boolean).join(' ');
}
function overlap(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0; for (const t of a) if (b.has(t)) inter++;
  return inter / Math.min(a.size, b.size);
}
function scoreDir(facturaRaw, hotelRaw) {
  if (!facturaRaw || !hotelRaw) return { score: 0, why: '' };
  const f = parseDir(facturaRaw), h = parseDir(hotelRaw);
  let score = 0; const why = [];
  if (f.cp && h.cp && f.cp === h.cp) { score += 45; why.push('CP'); }
  else if (f.cp && h.cp && f.cp.slice(0, 2) === h.cp.slice(0, 2)) { score += 8; why.push('prov'); }
  const ov = overlap(f.tokens, h.tokens);
  if (ov > 0) { score += Math.round(ov * 45); why.push('via' + (ov * 100 | 0)); }
  if (f.numero && h.numero && f.numero === h.numero && ov > 0) { score += 15; why.push('nº'); }
  return { score, why: why.join('+') };
}

// ---------- Compatibilidad esquema nuevo <-> antiguo ----------
const dirInstalRaw = dirToRaw(datos.direccion_instalacion);
const dirFiscalRaw = dirToRaw(datos.direccion_fiscal || datos.hotel_direccion);
const razonSocial  = datos.destinatario_razon_social || datos.hotel_destino || '';

datos.hotel_destino         = razonSocial || null;
datos.hotel_destino_cif     = datos.destinatario_cif || datos.hotel_destino_cif || null;
datos.hotel_direccion       = dirFiscalRaw || datos.hotel_direccion || null;
datos.direccion_instalacion = dirInstalRaw || null;

// ---------- Matching ----------
const UMBRAL_INSTALACION = 35;
const UMBRAL_FISCAL      = 50;

// Sociedad del destinatario (para desambiguar hoteles con el mismo nombre en
// distintas sociedades, p.ej. 'Alda Fogar Natural' existe en Compostela=118 y Castilla=203).
// ─────────────────────────────────────────────────────────────────────
// SOCIEDAD ANCLADA POR CIF (dato duro y fiable)
// El CIF del destinatario de la factura identifica la sociedad sin ambigüedad.
// Buscamos ese CIF en las compañías de Odoo (res.company.vat) para obtener la
// sociedad autoritativa (id + nombre). A partir de ahí, un hotel "es de la
// sociedad correcta" si su company_odoo_id coincide con el id de esa compañía.
// Esto es infalible frente a la variante anterior (comparar textos de razón
// social), que fallaba con nombres parecidos o abreviados.
// ─────────────────────────────────────────────────────────────────────
const _GEN = new Set(['alda','hotel','hoteles','sociedad','limitada','anonima','unipersonal','slu','sau','sl','sa','costes','generales','general','coste']);
const _sigWords = s => norm(s).split(' ').filter(w => w.length >= 4 && !_GEN.has(w));
const normCif = v => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^ES/, '');

let _companies = [];
try { _companies = $('Code_Companies_JSON').first().json.companies || []; } catch(e) {}

// Sociedad identificada por el CIF de la factura
const _cifFactura = normCif(datos.destinatario_cif);
let _socCif = null; // { id, name }
if (_cifFactura) {
  const comp = _companies.find(co => normCif(co.vat) === _cifFactura);
  if (comp) _socCif = { id: comp.id, name: comp.name };
}

// Fallback por texto de la razón social (solo si no hay CIF utilizable)
const _socDestNorm = norm(datos.destinatario_razon_social || datos.hotel_destino || '');
const _wDest = new Set(_sigWords(_socDestNorm));

// Sabemos la sociedad si la tenemos por CIF o, en su defecto, por texto.
const _sociedadConocida = !!_socCif || _wDest.size > 0;

function _mismaSociedad(h) {
  // 1) Vía dura: enlazar por id de compañía (CIF → company.id === hotel.company_odoo_id)
  if (_socCif) {
    if (h.company_odoo_id != null && String(h.company_odoo_id) === String(_socCif.id)) return true;
    // respaldo por nombre de sociedad si el hotel no trae company_odoo_id
    if (h.company_odoo_id == null) {
      const wh = new Set(_sigWords(h.sociedad || ''));
      for (const w of _sigWords(_socCif.name)) if (wh.has(w)) return true;
    }
    return false;
  }
  // 2) Vía texto (sin CIF): comparar palabras significativas de la razón social
  if (!_wDest.size) return false;
  const wh = new Set(_sigWords(h.sociedad || ''));
  for (const w of _wDest) if (wh.has(w)) return true;
  return false;
}



// Puntúa direcciones. Si se conoce la sociedad del destinatario, PREFIERE hoteles
// de esa sociedad: primero busca el mejor dentro de la sociedad correcta; solo si
// ninguno llega, considera el resto. Así 'San Pedro 37' + Alda Compostela → 118,
// no 203 (mismo nombre pero sociedad Castilla).
function mejorPorDireccion(dirRaw) {
  let best = null, bestScore = 0, bestWhy = '', bestSoc = null, bestScoreSoc = 0, bestWhySoc = '';
  for (const h of HOTELES) {
    const r = scoreDir(dirRaw, h.direccion);
    if (r.score > bestScore) { bestScore = r.score; best = h; bestWhy = r.why; }
    if (_mismaSociedad(h) && r.score > bestScoreSoc) { bestScoreSoc = r.score; bestSoc = h; bestWhySoc = r.why; }
  }
  // Si hay un match en la sociedad correcta que supera el umbral mínimo de instalación,
  // se prefiere aunque su score sea algo menor que un match global de otra sociedad.
  if (bestSoc && bestScoreSoc >= 35) {
    return { best: bestSoc, bestScore: bestScoreSoc, bestWhy: bestWhySoc + '+soc' };
  }
  return { best, bestScore, bestWhy };
}

let match = null, metodo = null, score = 0, motivo = '', confianza = 'baja';

// ═══════════════════════════════════════════════════════════════════════
// MATCHING DE HOTEL — Arquitectura IA-autoritativa
// ───────────────────────────────────────────────────────────────────────
// La IA (Gemini) es el MATCHER PRINCIPAL: recibe la lista completa de hoteles
// (código|nombre|dirección|sociedad) y elige el hotel razonando sobre nombre,
// dirección de instalación y dirección fiscal a la vez. Un LLM hace ese fuzzy
// matching mucho mejor que el solapamiento de tokens.
//
// El scorer determinista por dirección YA NO COMPITE: solo CONFIRMA (sube la
// confianza si coincide con la IA) o actúa de RESERVA (cuando la IA no da
// código). Nunca sobreescribe a la IA. Así se elimina la reconciliación
// "scorer vs IA" que era la fuente de los bugs recurrentes.
//
// El guardarraíl de sociedad (regla dura y fiable) se aplica después en
// Build_HTML_Centros: si la sociedad del hotel elegido no coincide con la
// sociedad destinataria, se ignora y va a Costes Generales de la correcta.
// ═══════════════════════════════════════════════════════════════════════

// --- Señal determinista por dirección (SOLO para confirmar / reserva) ---
// Se calcula el mejor candidato por instalación, concepto y fiscal, con
// preferencia de sociedad. No decide por sí solo salvo que la IA calle.
// --- Señal por dirección (instalación + concepto; NUNCA fiscal) ---
// La dirección FISCAL de la factura es la sede social genérica ("Costa San
// Marcos 22"), compartida por todas las sociedades, así que jamás debe elegir
// un hotel concreto (producía falsos positivos como asignar San Bieito). La
// sociedad se determina por el CIF, no por la dirección fiscal.
function mejorSenalDireccion() {
  const intentos = [];
  if (dirInstalRaw) intentos.push(['instalacion', mejorPorDireccion(dirInstalRaw)]);
  if (datos.concepto) intentos.push(['concepto', mejorPorDireccion(String(datos.concepto))]);
  let mejor = null;
  for (const [tipo, r] of intentos) {
    if (r.best && (!mejor || r.bestScore > mejor.score)) {
      mejor = { hotel: r.best, score: r.bestScore, why: r.bestWhy, tipo };
    }
  }
  return mejor;
}
const senalDir = mejorSenalDireccion();

// --- Señal por NOMBRE del hotel en el texto de la factura (la MÁS fiable) ---
// Si el nombre de un hotel de la lista aparece literalmente en el concepto o
// las líneas de la factura, ese es el hotel. Es una coincidencia de texto
// exacta (no fuzzy), así que es la señal más fuerte. Desambigua nombres
// duplicados (dos "Fogar Natural") por la sociedad del destinatario.
function matchPorNombre() {
  const partes = [datos.concepto, datos.detalle_lineas, datos.detalle, datos.numero_pedido];
  try {
    if (Array.isArray(datos.centros_lista))
      partes.push(datos.centros_lista.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
  } catch(e) {}
  const texto = norm(partes.filter(Boolean).join(' '));
  if (!texto) return null;
  const GEN = new Set(['alda','hotel','hoteles','apartamentos','apartamento','apartahotel','hostal',
    'albergue','pension','residencia','de','del','la','el','los','las','y','en','santiago','compostela']);
  const cands = [];
  for (const h of HOTELES) {
    const toks = norm(h.nombre).split(' ').filter(w => w.length >= 4 && !GEN.has(w));
    if (!toks.length) continue;
    const todosPresentes = toks.every(t => texto.includes(t));
    // Exigimos que TODOS los tokens distintivos del nombre estén, y que el nombre
    // tenga sustancia (>=2 tokens, o 1 token largo >=6) para evitar falsos positivos.
    const suficiente = todosPresentes && (toks.length >= 2 || (toks.length === 1 && toks[0].length >= 6));
    if (suficiente) cands.push({ hotel: h, toks: toks.length });
  }
  if (!cands.length) return null;
  const enSoc = cands.filter(x => _mismaSociedad(x.hotel));
  if (_sociedadConocida) {
    // Sociedad conocida: solo aceptamos un hotel de esa sociedad (desambigua duplicados)
    if (!enSoc.length) return null;
    enSoc.sort((a,b) => b.toks - a.toks);
    return enSoc[0].hotel;
  }
  // Sociedad desconocida: mejor candidato por nº de tokens; si hay empate, no arriesgamos
  cands.sort((a,b) => b.toks - a.toks);
  if (cands.length > 1 && cands[0].toks === cands[1].toks) return null;
  return cands[0].hotel;
}
const nombreMatch = matchPorNombre();

// --- Código que propuso la IA ---
const codigoIA = datos.codigo_hotel_ia && /^\d+$/.test(String(datos.codigo_hotel_ia).trim())
  ? String(datos.codigo_hotel_ia).trim().padStart(3, '0') : null;
const hotelIA = codigoIA ? HOTELES.find(h => String(h.codigo).padStart(3, '0') === codigoIA) : null;

// La regla dura: el hotel debe pertenecer a la sociedad del destinatario.
const iaEnSociedadCorrecta = hotelIA && (!_sociedadConocida || _mismaSociedad(hotelIA));

if (nombreMatch) {
  // ── PRIORIDAD MÁXIMA: el NOMBRE del hotel aparece literal en la factura ──
  match = nombreMatch;
  metodo = 'nombre';
  confianza = 'alta';
  motivo = `Hotel identificado por NOMBRE en la factura → ${nombreMatch.codigo} ${nombreMatch.nombre}`;
  if (hotelIA && String(hotelIA.codigo) === String(nombreMatch.codigo)) motivo += ' (IA coincide)';
  else if (hotelIA) motivo += ` (IA sugería ${codigoIA}; prevalece el nombre explícito)`;
} else if (hotelIA && !iaEnSociedadCorrecta) {
  // ── LA IA SE EQUIVOCÓ DE SOCIEDAD ────────────────────────────────────
  // Dos hoteles con el MISMO NOMBRE en sociedades distintas y la IA eligió el
  // de la sociedad equivocada. Se corrige por dirección dentro de la sociedad
  // correcta; si no hay, se deja sin match → Costes Generales.
  if (senalDir && _mismaSociedad(senalDir.hotel) && senalDir.score >= UMBRAL_INSTALACION) {
    match = senalDir.hotel; metodo = 'correccion_sociedad'; score = senalDir.score;
    confianza = senalDir.score >= 55 ? 'media' : 'baja';
    motivo = `IA sugirió ${codigoIA} ${hotelIA.nombre} (sociedad distinta); corregido por dirección → ${senalDir.hotel.codigo} ${senalDir.hotel.nombre} (${senalDir.why}, ${senalDir.score})`;
  } else {
    match = null;
    motivo = `IA sugirió ${codigoIA} ${hotelIA.nombre} de otra sociedad y no hay hotel de la sociedad correcta que encaje → costes generales`;
  }
} else if (hotelIA) {
  // ── LA IA MANDA (hotel en la sociedad correcta) ──────────────────────
  match = hotelIA;
  metodo = 'ia';
  confianza = ['alta','media','baja'].includes(datos.confianza_hotel) ? datos.confianza_hotel : 'media';
  const mismoCodigo = senalDir && String(senalDir.hotel.codigo).padStart(3,'0') === codigoIA;
  if (mismoCodigo) {
    confianza = 'alta';
    motivo = `Hotel ${codigoIA} ${hotelIA.nombre} — IA + dirección coinciden (${senalDir.why}, ${senalDir.score})`;
  } else if (senalDir && senalDir.score >= 55 && /nº/.test(senalDir.why) && _mismaSociedad(senalDir.hotel)) {
    confianza = 'baja';
    motivo = `Hotel ${codigoIA} ${hotelIA.nombre} [IA] — ATENCIÓN: la dirección apuntaba fuerte a ${senalDir.hotel.codigo} ${senalDir.hotel.nombre} (${senalDir.why}, ${senalDir.score}); verificar`;
  } else {
    motivo = `Hotel ${codigoIA} ${hotelIA.nombre} — identificado por IA (confianza ${confianza})`;
    if (senalDir) motivo += ` | señal dir.: ${senalDir.hotel.codigo}/${senalDir.score}(${senalDir.why})`;
  }
} else if (senalDir && (
    // ── RESERVA: sin nombre ni pista IA → dirección (instalación/concepto) ──
    (senalDir.tipo === 'instalacion' && senalDir.score >= UMBRAL_INSTALACION) ||
    (senalDir.tipo === 'concepto' && senalDir.score >= 45 && /via\d/.test(senalDir.why) && (/nº/.test(senalDir.why) || /CP/.test(senalDir.why)))
  )) {
  match = senalDir.hotel;
  metodo = senalDir.tipo;
  score = senalDir.score;
  confianza = senalDir.score >= 55 ? 'media' : 'baja';
  motivo = `Sin nombre ni pista IA — dirección (${senalDir.tipo}) → ${senalDir.hotel.codigo} ${senalDir.hotel.nombre} (${senalDir.why}, ${senalDir.score})`;
}

// ---------- Salida ----------
if (match) {
  datos.codigo_hotel_ia = String(match.codigo);
  datos.confianza_hotel = confianza;
} else {
  datos.codigo_hotel_ia = null;
  datos.confianza_hotel = 'baja';
  let _diag = '';
  try {
    const _rc = mejorPorDireccion(String(datos.concepto || ''));
    const _rf = mejorPorDireccion(dirFiscalRaw || '');
    _diag = ` | concepto="${String(datos.concepto||'').slice(0,60)}" mejorConcepto=${_rc.best?_rc.best.codigo+'/'+_rc.bestScore+'('+_rc.bestWhy+')':'-'}` +
            ` mejorFiscal=${_rf.best?_rf.best.codigo+'/'+_rf.bestScore:'-'} iaPista=${datos.codigo_hotel_ia_original||'null'}`;
  } catch(e) {}
  motivo = `Sin identificación de hotel (instal="${dirInstalRaw}" fiscal="${dirFiscalRaw}", hoteles=${HOTELES.length})${_diag}`;
}


datos.match_metodo = metodo;
datos.match_score  = score;
datos.match_motivo = motivo;
datos.match_hotel  = match ? match.nombre : null;
datos.match_hoteles_evaluados = HOTELES.length;
// Sociedad identificada por CIF (autoritativa) — para Costes Generales y validación aguas abajo
datos.sociedad_cif_id = _socCif ? _socCif.id : null;
datos.sociedad_cif_nombre = _socCif ? _socCif.name : null;
// Diagnóstico: nº de hoteles de la sociedad identificada (contexto útil en el log)
if (_socCif) {
  datos.sociedad_cif_num_hoteles = HOTELES.filter(h => _mismaSociedad(h)).length;
}

return { json: datos, binary: $input.item.binary };

// Detectar TODOS los adjuntos PDF — 1 item por PDF
const items = $input.all();
let binary = {};
let triggerJson = {};

try {
  const triggerItems = $('Email Trigger (IMAP)1').all();
  if(triggerItems.length > 0) {
    binary = triggerItems[0].binary || {};
    triggerJson = triggerItems[0].json || {};
  }
} catch(e) {
  if(items.length > 0) {
    binary = items[0].binary || {};
    triggerJson = items[0].json || {};
  }
}

const KEYWORDS_NO_FACTURA = ['albaran', 'albarán', 'delivery', 'presupuesto', 'quote', 'contrato', 'contract'];
const esNoFactura = nombre => KEYWORDS_NO_FACTURA.some(k => nombre.toLowerCase().includes(k));

const pdfs = [];
for(const [key, val] of Object.entries(binary)){
  if(!val) continue;
  const mime = val.mimeType || '';
  const fname = val.fileName || val.filename || '';
  if(mime === 'application/pdf' || fname.toLowerCase().endsWith('.pdf')){
    if(!esNoFactura(fname)){
      pdfs.push({ key, name: fname, binary: val });
    }
  }
}

if(pdfs.length === 0){
  return [{
    json: { ...triggerJson, detected_pdf_key: null, detected_pdf_name: '', total_pdfs: 0, pdf_index: 0 },
    binary: binary,
    pairedItem: { item: 0 }
  }];
}

return pdfs.map((pdf, index) => ({
  json: {
    ...triggerJson,
    detected_pdf_key: pdf.key,
    detected_pdf_name: pdf.name,
    total_pdfs: pdfs.length,
    pdf_index: index + 1,
    all_pdfs: pdfs.map(p => p.name).join(', ')
  },
  binary: { attachment_0: pdf.binary },
  pairedItem: { item: 0 }
}));

// Construye el cuerpo para POST /api/webhook/factura del portal.
const d = $('Build_HTML_Centros').item.json;

// PDF en base64 — getBinaryDataBuffer() es el helper soportado en Code Node (binaryToBuffer
// dio 'not supported in the Code Node' en pruebas reales). $itemIndex en modo
// runOnceForEachItem corresponde al item actual sea cual sea la rama de origen.
let pdf_base64 = '';
let _pdf_debug = 'not-attempted';
try {
  const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'pdf_final');
  pdf_base64 = buf.toString('base64');
  _pdf_debug = 'ok, bytes=' + buf.length;
} catch(e) { _pdf_debug = 'ERROR: ' + (e?.message || String(e)); }


const token = (d.factura_numero ? String(d.factura_numero).replace(/[^A-Za-z0-9]/g,'') : 'fac') + '_' + Date.now();

return { json: {
  token,
  estado:              d.tiene_error_grave ? 'pendiente' : 'aprobada',
  n8n_webhook_url:    'https://n8n.gestionalda.es/webhook/factura-validada',
  factura_numero:     d.factura_numero || null,
  factura_fecha:      d.factura_fecha || null,
  proveedor_nombre:   d.proveedor_nombre || null,
  proveedor_cif:      d.proveedor_cif || d.destinatario_cif || null,
  importe_total:      d.importe_total ?? null,
  base_imponible:     d.base_imponible ?? null,
  forma_pago_detalle: d.forma_pago_detalle || null,
  concepto:           d.concepto || null,
  hotel_nombre_odoo:  d.hotel_nombre_odoo || d.match_hotel || null,
  codigo_hotel:       d.codigo_hotel || null,
  dw_hotel:           d.dw_hotel || null,
  dw_fpago:           d.dw_fpago || '00',
  sociedad:           d.sociedad || null,
  es_costes_generales: d.es_costes_generales ? 1 : 0,
  email_remitente:    d.email_remitente || '',
  asunto_email:       d.asunto_email || '',
  detected_pdf_name:  d.detected_pdf_name || ((d.factura_numero||'factura')+'.pdf'),
  errores_graves:     d.errores_graves || [],
  errores_leves:      d.errores_leves || [],
  motivo_revision:    d.motivo_revision || null,
  solo_enlace:        d.solo_enlace ? 1 : 0,
  enlace_descarga:    d.enlace_descarga || null,
  enlaces_detectados: d.enlaces_detectados || [],
  requiere_acceso_portal: d.requiere_acceso_portal ? 1 : 0,
  pdf_base64,
  _pdf_debug,
} };

// El portal manda: { accion, token, hotel, fpago, pdf_base64, ... }
const b = $json.body || $json;
if (b.accion !== 'aprobar') {
  return [{ json: { archivar: false, accion: b.accion || 'desconocida', token: b.token || null, nota: b.nota || '' } }];
}
if (!b.pdf_base64) {
  return [{ json: { archivar: false, error: 'sin pdf_base64', token: b.token || null } }];
}
const buf = Buffer.from(b.pdf_base64, 'base64');
const fileName = String(b.token || 'factura').replace(/[^A-Za-z0-9._-]/g,'_') + '.pdf';
return [{
  json: { archivar: true, token: b.token, dw_hotel: b.hotel, dw_fpago: b.fpago || '00',
          dw_nota: 'Validado portal ' + (b.token||''), dw_nota2: '' },
  binary: { pdf_final: await this.helpers.prepareBinaryData(buf, fileName, 'application/pdf') }
}];

