parameters.jsCode:
const items = $input.all();
let t = {};
try { t = $('Email Trigger (IMAP)1').first().json || {}; } catch(e) {}

const html = t.textHtml || t.html || t.bodyHtml || '';
const text = t.textPlain || t.text || t.bodyText || '';
const asunto = t.subject || '';
const remitente = t.from?.value?.[0]?.address || t.from?.address || String(t.from || '');

const urls = [];
const reHref = /href\s*=\s*["']([^"']+)["']/gi;
let m;
while((m = reHref.exec(html)) !== null){ urls.push(m[1]); }
const reUrl = /https?:\/\/[^\s"'<>\)\]]+/gi;
for(const src of [text, html]){ let u; while((u = reUrl.exec(src)) !== null){ urls.push(u[0]); } }

const limpio = u => String(u).replace(/&amp;/g,'&').trim().replace(/[.,;]+$/,'');
const vistos = new Set();
const todas = [];
for(const u of urls.map(limpio)){
  if(!u || !/^https?:\/\//i.test(u)) continue;
  const k = u.toLowerCase();
  if(vistos.has(k)) continue;
  vistos.add(k); todas.push(u);
}

const RUIDO = ['unsubscribe','/baja','darse-de-baja','mailto:','facebook.com','twitter.com','x.com/','linkedin.com','instagram.com','youtube.com','whatsapp.com','privacid','privacy','aviso-legal','/legal','cookie','t.me/','goo.gl/maps','maps.google'];
const esRuido = u => RUIDO.some(r => u.toLowerCase().includes(r));
const KW = ['descarg','download','factura','invoice','document','/pdf','.pdf','visualiz','ver-factura','verfactura','recibo','justificante','comprobante','/dl/','/file'];
const score = u => { const s=u.toLowerCase(); return KW.reduce((acc,k)=> acc + (s.includes(k)?1:0), 0); };

const candidatas = todas.filter(u => !esRuido(u));
candidatas.sort((a,b) => score(b) - score(a));
const enlaceDescarga = (candidatas.find(u => score(u) > 0)) || candidatas[0] || null;

// Detectar si el correo pide acceder a una PLATAFORMA/PORTAL del proveedor en
// vez de dar un enlace de descarga directo (caso distinto: no hay nada que
// clicar, hay que iniciar sesión en el sitio del proveedor con credenciales).
const cuerpoLower = (text + ' ' + html.replace(/<[^>]+>/g, ' ')).toLowerCase();
const KW_PORTAL = ['nuestro portal', 'área de cliente', 'area de cliente', 'accede a tu cuenta',
  'inicia sesión', 'inicia sesion', 'plataforma de facturación', 'plataforma de facturacion',
  'portal del proveedor', 'portal de facturación', 'portal de facturacion', 'zona de clientes',
  'inicia sesion en', 'accede a nuestra plataforma', 'consulta tu factura en', 'consultar en la web'];
const requierePortal = KW_PORTAL.some(k => cuerpoLower.includes(k));

let proveedorAprox = null;
try { const dom = (remitente.split('@')[1] || '').split('.')[0]; if(dom) proveedorAprox = dom.charAt(0).toUpperCase() + dom.slice(1); } catch(e){}

const baseJson = items[0]?.json || {};
return [{
  json: {
    ...baseJson,
    es_factura: true,
    solo_enlace: true,
    enlace_descarga: enlaceDescarga,
    enlaces_detectados: candidatas.slice(0, 10),
    requiere_acceso_portal: requierePortal,
    proveedor_nombre: baseJson.proveedor_nombre || proveedorAprox,
    asunto_email: asunto,
    email_remitente: remitente,
    detected_pdf_name: baseJson.detected_pdf_name || (asunto ? asunto.slice(0,60) : 'factura_sin_adjunto'),
    factura_numero: null
  },
  binary: {}
}];

// Facturas sin adjunto original (solo enlace de descarga): no hay nada que
// fusionar. binary.pdf_final ya viene puesto por Restore_Binary_Centros
// (es el resumen con los datos extraidos del cuerpo del email).
return { json: $input.item.json, binary: $input.item.binary };

// Empaqueta las compañías (res.company) en un único item para que el
// siguiente nodo Odoo (Get_Cities → res.city) se ejecute una sola vez.
// Las compañías se seguirán leyendo aguas abajo via $('Get_Companies').all().
return [{ json: { companies_count: $input.all().length } }];
